sp_widget.client_script:
api.controller = function($scope) {
  $scope.data = { status: "⏳ Loading models...", modelsLoaded: false };

  const video = document.getElementById('faceVideo');
  const MODEL_URL = 'https://cdn.jsdelivr.net/npm/face-api.js/weights';

  async function loadModels() {
    await faceapi.nets.tinyFaceDetector.loadFromUri(MODEL_URL);
    await faceapi.nets.faceLandmark68Net.loadFromUri(MODEL_URL);
    await faceapi.nets.faceRecognitionNet.loadFromUri(MODEL_URL);

    $scope.$apply(() => {
      $scope.data.modelsLoaded = true;
      $scope.data.status = "✅ Models loaded. Ready for login.";
    });

    navigator.mediaDevices.getUserMedia({ video: true }).then(stream => {
      video.srcObject = stream;
    });
  }

  loadModels();

  this.loginFace = async function() {
    const detection = await faceapi
      .detectSingleFace(video, new faceapi.TinyFaceDetectorOptions())
      .withFaceLandmarks()
      .withFaceDescriptor();

    if (!detection) {
      $scope.$apply(() => $scope.data.status = "❌ No face detected. Try again.");
      return;
    }

    const embedding = Array.from(detection.descriptor);

    // Ask server for stored embeddings
    api.server.get({ action: "getEmbeddings" }).then(function(res) {
      if (!res.data.users || res.data.users.length === 0) {
        $scope.data.status = "❌ No registered users found.";
        $scope.$apply();
        return;
      }

      let bestMatch = null;
      let bestDistance = 1.0;

      res.data.users.forEach(u => {
        let storedEmbedding = JSON.parse(u.u_face_embedding);
        let distance = faceapi.euclideanDistance(embedding, storedEmbedding);
        if (distance < bestDistance) {
          bestDistance = distance;
          bestMatch = u;
        }
      });

      if (bestDistance < 0.6) {
        $scope.data.status = "✅ Face recognized: " + bestMatch.u_name;
      } else {
        $scope.data.status = "❌ Face not recognized.";
      }
      $scope.$apply();
    });
  };
};

sp_widget.script:
(function() {
  if (input && input.action == "getEmbeddings") {
    var gr = new GlideRecord("x_938076_now_utils_face_registry_details");
    gr.query();
    var users = [];
    while (gr.next()) {
      users.push({
        u_name: gr.u_name.toString(),
        u_face_embedding: gr.u_face_embedding.toString()
      });
    }
    data.users = users;
  }
})();
